package main

import (
	"bufio"
	"io"
)

// ❌ OLD: Holding the concrete writer behind an interface forces a
// dynamic dispatch (itab lookup + indirect call) on every Write, and
// the interface conversion can cause heap allocation for the
// interface header. In a hot loop, that indirection is measurable.
func writeAll(f *os.File, b []byte, n int) {
	var w io.Writer = bufio.NewWriter(f) // ❌ OLD: dynamic type
	for i := 0; i < n; i++ {
		w.Write(b) // ❌ OLD: indirect call through the itab each iteration
	}
}

// The compiler cannot inline the call because the receiver is only
// known at runtime through the interface.

package main

import "bufio"

// ✅ NEW: Use the concrete type where the code is hot and the type is
// fixed. w.Write is a direct call the compiler can inline; no itab, no
// interface header allocation, no dynamic dispatch.
func writeAll(f *os.File, b []byte, n int) {
	w := bufio.NewWriter(f) // ✅ NEW: static type known
	for i := 0; i < n; i++ {
		w.Write(b) // ✅ NEW: direct call, inlinable
	}
}

// Keep interfaces at API boundaries (for polymorphism, testing, and
// decoupling) and use concrete types internally where performance and
// inlining matter.
